<article class="content-card card glass reveal"><a class="card-cover" aria-label="<?= e($entry['title']) ?>" href="<?= e(item_url($entry)) ?>"><img src="<?= e(cover($entry)) ?>" alt="" loading="lazy" width="640" height="440"><?php if ($entry['access_level'] !== 'public'): ?><span class="cover-badge"><?= icon('lock') ?><?= t($entry['access_level'] === 'paid' ? 'Paid access' : $entry['access_level']) ?></span><?php endif ?></a><div class="card-content"><div class="card-kicker"><span><?= e($entry['category_name'] ?: tr($entry['kind'])) ?></span><?php if ($s->get('show_dates')): ?><time datetime="<?= e(date('c',(int)$entry['created_at'])) ?>"><?= dt((int)$entry['created_at'],'m.d') ?></time><?php endif ?></div><h3 class="card-title"><a href="<?= e(item_url($entry)) ?>"><?= e($entry['title']) ?></a></h3><p class="card-excerpt"><?= e($entry['excerpt']) ?></p><?php if ($entry['kind'] === 'product'): ?><div class="card-price"><?= e(item_price($entry)) ?><small><?= t('Thoughtfully selected') ?></small></div><?php endif ?><div class="card-meta"><?php if ($s->get('show_authors')): ?><a class="author" href="<?= e(url('user',['id'=>(int)$entry['author_id']])) ?>"><?= avatar($entry,'tiny') ?><span><?= e($entry['display_name']) ?></span></a><?php endif ?><?php if ($s->get('show_stats')): ?><span class="meta-right"><?= icon('eye') ?><?= number_format((int)$entry['view_count']) ?></span><?php endif ?></div></div></article>
